    "topic": "Fed speakers / FOMC rate path signals",
    "why_gold_cares": "Shifts in expected policy rate move real yields and the dollar, the dominant gold drivers",
    "impact_threshold": "Unexpected hawkish/dovish pivot from voting members or Chair",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "PCE / core inflation prints",
    "why_gold_cares": "Inflation surprises reprice Fed cut odds and real yields rapidly",
    "impact_threshold": "Deviation from consensus by 0.1pp+ on core",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "DXY breakout above/below recent range",
    "why_gold_cares": "Dollar strength priced gold from 4173 to 4088, near-term inverse correlation confirmed",
    "impact_threshold": "Sustained DXY move beyond intraday high/low with follow-through",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "10Y nominal & real yield moves",
    "why_gold_cares": "Higher real yields raise opportunity cost of holding non-yielding gold",
    "impact_threshold": "Daily move of 5bps+ or auction-driven repricing",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "Geopolitical shocks (Middle East, Ukraine, sanctions)",
    "why_gold_cares": "Safe-haven bid can override macro flows on escalation",
    "impact_threshold": "Sudden escalation, ceasefire collapse, or new sanctions regime",
    "directional_risk": "BULLISH_GOLD"
  },
  {
    "topic": "Central bank gold demand / reserve flows",
    "why_gold_cares": "Structural buying supports the floor; pauses can deepen corrections",
    "impact_threshold": "Reported large official-sector buying or selling",
    "directional_risk": "BULLISH_GOLD"
  },
  {
    "topic": "Treasury auction demand & TGA dynamics",
    "why_gold_cares": "Weak auctions push yields up; liquidity drains affect risk and dollar",
    "impact_threshold": "Tail in auction or sharp bid-to-cover drop",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "Banking / credit stress events",
    "why_gold_cares": "Systemic stress triggers safe-haven and rate-cut bets",
    "impact_threshold": "Named institution distress or funding-market dislocation",
    "directional_risk": "BULLISH_GOLD"
  }
]
